//! UI icon art: PNGs generated by `assets/vectorcraft/make_icons.py` (128 px), embedded in the
//! binary and registered with hearth_ui at the exact pixel size they're drawn at (the image atlas
//! has no mipmaps). Reloaded if the display scale changes.

use hearth_ui::{ImageId, Ui};
use sim::data::Category;

macro_rules! icons {
    ($($v:ident => $file:literal),* $(,)?) => {
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        pub enum Icon { $($v),* }

        const PNGS: &[&[u8]] = &[$(include_bytes!(concat!("../../../assets/ui/icons/", $file, ".png"))),*];
    };
}

icons! {
    Room => "room", Wall => "wall", KnockDown => "knock_down", Door => "door", Window => "window",
    Floor => "floor", RipFloor => "rip_floor", Stairs => "stairs", Dig => "dig", Roof => "roof",
    NoRoof => "no_roof", Terrain => "terrain",
    Seating => "seating", Sleeping => "sleeping", Surfaces => "surfaces", Kitchen => "kitchen",
    Bathroom => "bathroom", Electronics => "electronics", Fun => "fun", Kids => "kids",
    Decor => "decor", Lighting => "lighting", Misc => "misc", Sell => "sell",
}

/// Icon sizes in points.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IconSize {
    /// Buy/Build catalog tiles.
    Tile,
    /// Inside small buttons and chips (1.35 em of their 13 pt label).
    Chip,
}

impl IconSize {
    pub const fn points(self) -> f32 {
        match self {
            IconSize::Tile => 30.0,
            IconSize::Chip => 13.0 * 1.35,
        }
    }
}

impl Icon {
    pub fn category(c: Category) -> Icon {
        match c {
            Category::Seating => Icon::Seating,
            Category::Sleeping => Icon::Sleeping,
            Category::Surfaces => Icon::Surfaces,
            Category::Kitchen => Icon::Kitchen,
            Category::Bathroom => Icon::Bathroom,
            Category::Electronics => Icon::Electronics,
            Category::Decor => Icon::Decor,
            Category::Lighting => Icon::Lighting,
            Category::Fun => Icon::Fun,
            Category::Kids => Icon::Kids,
            Category::Misc => Icon::Misc,
        }
    }
}

#[derive(Default)]
pub struct Icons {
    /// Pixels per point the images were made for (0 = not loaded).
    ppp: f32,
    /// [tile, chip] per icon.
    ids: Vec<[ImageId; 2]>,
}

impl Icons {
    /// Registers the icons for the current display scale (once, and again if it changes).
    pub fn ensure(&mut self, ui: &mut Ui) {
        let ppp = ui.input.ppp;
        if self.ppp == ppp {
            return;
        }
        self.ppp = ppp;
        let px = |s: IconSize| (s.points() * ppp).ceil() as u32;
        let loaded: Result<Vec<_>, _> = PNGS
            .iter()
            .map(|png| Ok([ui.images.add_png(png, Some(px(IconSize::Tile)))?, ui.images.add_png(png, Some(px(IconSize::Chip)))?]))
            .collect::<Result<_, hearth_ui::ImageError>>()
            .map_err(|e| e.to_string());
        match loaded {
            Ok(ids) => self.ids = ids,
            Err(e) => {
                log::warn!("UI icons not loaded: {e}");
                self.ids.clear();
            }
        }
    }

    /// The image for `icon` at `size` (None if loading failed).
    pub fn get(&self, icon: Icon, size: IconSize) -> Option<ImageId> {
        self.ids.get(icon as usize).map(|ids| ids[size as usize])
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_icon_decodes_at_both_sizes() {
        let mut ui = Ui::new();
        ui.input.ppp = 2.0;
        let mut icons = Icons::default();
        icons.ensure(&mut ui);
        assert_eq!(icons.ids.len(), PNGS.len());
        let id = icons.get(Icon::Sell, IconSize::Chip).unwrap();
        assert_eq!(ui.images.size(id).x, (IconSize::Chip.points() * 2.0).ceil());
        assert_eq!(ui.images.size(icons.get(Icon::Terrain, IconSize::Tile).unwrap()).x, 60.0);
    }
}
